export function getDistrictColorById(districtId) {
    const index = districtIdToIndex[districtId];
    return index !== undefined ? districts[index] : '#cccccc';
}

export function getDistrictHoverColorById(districtId) {
    const index = districtIdToIndex[districtId];
    return index !== undefined ? districtsHover[index] : '#dddddd';
}

